package com.example.examplemod.cargo.center;

import com.example.examplemod.auth.PlayerNames;
import com.example.examplemod.cargo.*;
import com.example.examplemod.city.CityManager;
import com.example.examplemod.economy.EconomyManager;
import com.example.examplemod.economy.company.CompanyBook;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
import java.util.*;

/** Authorized native company workspace. Registered production is real Cargo infrastructure. */
@EventBusSubscriber(modid="createcityexpansioncore")
public final class CompanyCenter {
    private CompanyCenter(){}
    private static CompanyBook book(ServerPlayer actor){return EconomyManager.get(actor.serverLevel()).companies();}
    public static void appendOwners(ServerPlayer actor,ListTag owners){for(var c:book(actor).all())if(book(actor).permits(c.id(),actor.getUUID(),CompanyBook.Permission.ASSETS)||book(actor).permits(c.id(),actor.getUUID(),CompanyBook.Permission.SPEND))option(owners,"COMPANY/"+c.id(),c.name(),"COMPANY");}
    public static void appendSubjects(ServerPlayer actor,ListTag subjects){for(var c:book(actor).all())if(!c.archived())option(subjects,"COMPANY/"+c.id(),c.name(),"COMPANY");}
    private static void option(ListTag list,String value,String name,String kind){if(list.size()>=256)return;var t=new CompoundTag();t.putString("Value",value);t.putString("Name",name);if(kind!=null)t.putString("OwnerKind",kind);list.add(t);}
    private static CompoundTag row(UUID id,String kind,String name,String state,UUID company){var t=new CompoundTag();t.putUUID("Id",id);t.putUUID("Company",company);t.putString("Kind",kind);t.putString("Name",name);t.putString("Status",state);t.put("Facts",new ListTag());return t;}
    private static void fact(CompoundTag row,String key,Object value){var t=new CompoundTag();t.putString("LabelKey","ccec.company."+key);t.putString("Value",Objects.toString(value,""));row.getList("Facts",10).add(t);}
    private static void keyFact(CompoundTag row,String key,String value){var t=new CompoundTag();t.putString("LabelKey","ccec.company."+key);t.putString("ValueKey","ccec.company.value."+value);row.getList("Facts",10).add(t);}
    private static void form(ListTag list,String action,String...fields){CenterForms.add(list,action,true,fields);}
    private static void formLabels(ListTag forms){for(Tag raw:forms){var form=(CompoundTag)raw;for(Tag fieldRaw:form.getList("Fields",10)){var f=(CompoundTag)fieldRaw;f.putString("LabelKey","ccec.company.field."+f.getString("Key"));f.putString("HintKey","ccec.company.hint."+f.getString("Key"));if(f.getString("Kind").equals("number")){f.putLong("Min",Set.of("Amount","Shares","Hours").contains(f.getString("Key"))?1:0);f.putLong("Max",switch(f.getString("Key")){case "TaxBps"->10_000;case "Hours"->720;case "Shares"->1_000_000_000;default->Long.MAX_VALUE;});}}}}
    public static CompoundTag snapshot(ServerPlayer actor,CompoundTag q){
        var econ=EconomyManager.get(actor.serverLevel());var b=econ.companies();UUID me=actor.getUUID();long now=System.currentTimeMillis();var all=new ArrayList<CompoundTag>();var choices=new CompoundTag();var companies=new ListTag();var cities=new ListTag();var taxCities=new ListTag();
        for(var city:CityManager.get(actor.serverLevel()).getCities()){option(cities,city.getId().toString(),city.getName(),null);if(city.isAdmin(me))option(taxCities,city.getId().toString(),city.getName(),null);}choices.put("Cities",cities);choices.put("TaxCities",taxCities);
        var players=new ListTag();for(var p:actor.getServer().getPlayerList().getPlayers())option(players,p.getUUID().toString(),p.getGameProfile().getName(),null);choices.put("Players",players);
        var assetOptions=new ListTag();for(var c:b.all()){
            if(c.archived()||!b.visible(c.id(),me))continue;option(companies,c.id().toString(),c.name(),"COMPANY");var r=row(c.id(),"company",c.name(),c.salaryDebt()>0?"BLOCKED":"AVAILABLE",c.id());r.putBoolean("Manage",b.permits(c.id(),me,CompanyBook.Permission.ASSETS));
            fact(r,"balance",econ.accounts().balance(CompanyBook.owner(c.id()))+" CR");fact(r,"salary_debt",c.salaryDebt()+" CR");fact(r,"road_debt",econ.roadTolls().totalDebt(CompanyBook.owner(c.id()))+" CR");fact(r,"revenue",c.revenue()+" CR");fact(r,"tax_paid",c.taxPaid()+" CR");fact(r,"tax_rate",percent(b.tax(c.city()).basisPoints()));fact(r,"salary_paid",c.salaryPaid()+" CR");fact(r,"shares",c.shares().getOrDefault(me,0)+" / "+c.totalShares());fact(r,"charter",c.charter());fact(r,"city",Optional.ofNullable(CityManager.get(actor.serverLevel()).getCity(c.city())).map(x->x.getName()).orElse(c.city().toString()));all.add(r);
            for(var e:c.employees()){var staff=row(CompanyBook.stable(c.id(),"employee/"+e.player()),"company_employee",c.name()+" · "+PlayerNames.name(actor.getServer(),e.player()),e.active()?"AVAILABLE":"COMPLETED",c.id());staff.putUUID("Employee",e.player());keyFact(staff,"role",e.role().name());fact(staff,"salary",e.salary()+" CR / 24h");fact(staff,"salary_debt",e.arrears()+" CR");all.add(staff);}
            for(var a:c.assets()){var asset=row(a.id(),"company_asset",c.name()+" · "+a.name(),"CONFIGURED",c.id());asset.putUUID("Reference",a.reference());asset.putString("AssetKind",a.kind().name());asset.putUUID("OpenId",a.reference());asset.putString("OpenKind",switch(a.kind()){case WAREHOUSE,PRODUCTION,STORE->"warehouse";case TRAIN->"train";case POINT->"point";case ROAD->"road";});keyFact(asset,"asset_kind",a.kind().name());fact(asset,"reference",a.reference());all.add(asset);}
            for(var warehouse:CargoWarehouseRegistry.get(actor.getServer()).all())if(CargoWarehouseRegistry.access(actor.getServer(),warehouse).owner().equals(CompanyBook.owner(c.id())))option(assetOptions,"WAREHOUSE/"+warehouse.id(),warehouse.name(),null);
            for(var train:CargoTrainRegistry.get(actor.getServer()).registrations())if(CargoOwners.get(actor.getServer()).owner("train/"+train.trainId(),train.ownerId()).equals(CompanyBook.owner(c.id())))option(assetOptions,"TRAIN/"+train.trainId(),train.displayName(),null);
            for(var point:CargoPointRegistry.get(actor.getServer()).points())if(CargoOwners.point(actor.getServer(),point).equals(CompanyBook.owner(c.id())))option(assetOptions,"POINT/"+point.id(),point.name(),null);
            for(var road:econ.roadTolls().roads())if(road.owner().equals(CompanyBook.owner(c.id())))option(assetOptions,"ROAD/"+road.id(),road.name(),null);
        }choices.put("Companies",companies);choices.put("Assets",assetOptions);
        for(var i:b.invites())if(i.player().equals(me)||b.permits(i.company(),me,CompanyBook.Permission.PERSONNEL)){var c=b.find(i.company()).orElseThrow();var r=row(i.id(),"company_invite",c.name()+" · "+PlayerNames.name(actor.getServer(),i.player()),i.expires()<now?"EXPIRED":"REQUESTED",i.company());r.putUUID("Player",i.player());r.putBoolean("GovernanceAppointment",i.appointment()!=null);keyFact(r,"role",i.role().name());if(i.appointment()!=null)keyFact(r,"decision","DIRECTOR_ACCEPTANCE");fact(r,"salary",i.salary()+" CR / 24h");fact(r,"expires",java.time.Instant.ofEpochMilli(i.expires()));all.add(r);}
        for(var contract:b.contracts())if(b.visible(contract.company(),me)||contract.counterparty().operates(actor.getServer(),me)){var c=b.find(contract.company()).orElseThrow();var r=row(contract.id(),"company_contract",c.name()+" · "+contract.counterparty().name(actor.getServer()),contract.state().name(),contract.company());keyFact(r,"contract_kind",contract.kind().name());fact(r,"amount",contract.amount()+" CR");fact(r,"quantity",contract.quantity());fact(r,"terms",contract.terms());fact(r,"reference",contract.reference());all.add(r);}
        for(var o:b.shareOffers())if(!o.closed()&&(o.seller().equals(me)||o.buyer().equals(me))){var c=b.find(o.company()).orElseThrow();var r=row(o.id(),"company_share_offer",c.name()+" · "+PlayerNames.name(actor.getServer(),o.seller())+" → "+PlayerNames.name(actor.getServer(),o.buyer()),o.expires()<now?"EXPIRED":"REQUESTED",o.company());r.putUUID("Seller",o.seller());r.putUUID("Buyer",o.buyer());fact(r,"shares",o.units()+" / "+c.totalShares());fact(r,"amount",o.price()+" CR");fact(r,"charter",c.charter());fact(r,"tax_rate",percent(b.tax(c.city()).basisPoints()));fact(r,"expires",java.time.Instant.ofEpochMilli(o.expires()));all.add(r);}
        for(var v:b.votes())if(b.visible(v.company(),me)||v.electorate().containsKey(me)){var c=b.find(v.company()).orElseThrow();var r=row(v.id(),"company_vote",c.name(),v.state().equals("OPEN")&&v.expires()<now?"EXPIRED":v.state(),v.company());keyFact(r,"decision",v.decision().name());fact(r,"votes",v.yes()+" / "+v.total());fact(r,"amount",v.amount());fact(r,"terms",v.text());if(v.target()!=null)fact(r,"reference",v.target());all.add(r);}
        var orders=new ListTag();for(var order:econ.cargo().orders())if(order.payer().operates(actor.getServer(),me)||order.seller().operates(actor.getServer(),me)||order.fees().stream().anyMatch(f->f.recipient().operates(actor.getServer(),me)))option(orders,order.id().toString(),order.id().toString().substring(0,8)+" · "+order.state()+" · "+order.total()+" CR",null);choices.put("CompanyOrders",orders);
        var paidRoadDebts=new ListTag();for(var debt:econ.roadTolls().debts())if(debt.paid()>0&&(debt.debtor().operates(actor.getServer(),me)||debt.creditor().operates(actor.getServer(),me)))option(paidRoadDebts,debt.id().toString(),debt.id().toString().substring(0,8)+" · "+debt.paid()+" CR",null);choices.put("RoadReceipts",paidRoadDebts);
        var result=new CompoundTag();result.putString("Section","companies");result.put("Choices",choices);var forms=new ListTag();form(forms,"COMPANY_CREATE","Name","City@Cities");if(!taxCities.isEmpty())form(forms,"COMPANY_TAX","City@TaxCities","TaxBps#0");
        UUID selected=q.hasUUID("Selected")?q.getUUID("Selected"):null;CompoundTag selectedRow=selected==null?null:all.stream().filter(t->t.getUUID("Id").equals(selected)).findFirst().orElse(null);
        if(selectedRow!=null){result.put("SelectedRow",selectedRow);var c=b.find(selectedRow.getUUID("Company")).orElseThrow();String kind=selectedRow.getString("Kind");
            if(kind.equals("company")){
                form(forms,"COMPANY_DEPOSIT","Amount#1");if(b.permits(c.id(),me,CompanyBook.Permission.SPEND))form(forms,"COMPANY_WITHDRAW","Amount#1");
                if(b.permits(c.id(),me,CompanyBook.Permission.PERSONNEL))form(forms,"COMPANY_INVITE","Player@Players","Role=ACCOUNTANT|MANAGER|LOGISTICIAN|WORKER","Salary#0");
                if(b.permits(c.id(),me,CompanyBook.Permission.ASSETS))form(forms,"COMPANY_ASSET_REGISTER","Asset@Assets","AssetKind=TRAIN|POINT|WAREHOUSE|PRODUCTION|STORE|ROAD");
                if(b.permits(c.id(),me,CompanyBook.Permission.TRADE)){form(forms,"COMPANY_CONTRACT_CREATE","ContractKind=SUPPLY|TRANSPORT","Order@CompanyOrders","Terms","Hours#168");form(forms,"COMPANY_INFRA_CONTRACT","RoadReceipt@RoadReceipts","Terms","Hours#168");}
                if(b.shareholder(c.id(),me)){form(forms,"COMPANY_SHARE_OFFER","Player@Players","Shares#1","Price#0","Hours#168");form(forms,"COMPANY_PROPOSE","Decision=DIRECTOR|CITY|CHARTER|ISSUE_SHARES|DIVIDEND|ARCHIVE","Player@Players","City@Cities","Amount#0","Terms");}
            }else if(kind.equals("company_invite")){if(selectedRow.getUUID("Player").equals(me)){form(forms,"COMPANY_ACCEPT_JOB");form(forms,"COMPANY_DECLINE_JOB");}if(!selectedRow.getBoolean("GovernanceAppointment")&&b.permits(c.id(),me,CompanyBook.Permission.PERSONNEL))form(forms,"COMPANY_CANCEL_INVITE");}
            else if(kind.equals("company_employee")){if(b.permits(c.id(),me,CompanyBook.Permission.PERSONNEL)){form(forms,"COMPANY_EMPLOYEE_ROLE","Role=ACCOUNTANT|MANAGER|LOGISTICIAN|WORKER");form(forms,"COMPANY_SALARY_OFFER","Salary#0");}if(b.permits(c.id(),me,CompanyBook.Permission.PERSONNEL)||selectedRow.getUUID("Employee").equals(me))form(forms,"COMPANY_EMPLOYEE_END");}
            else if(kind.equals("company_asset")&&b.permits(c.id(),me,CompanyBook.Permission.ASSETS))form(forms,"COMPANY_ASSET_REMOVE");
            else if(kind.equals("company_contract")){var contract=b.contracts().stream().filter(x->x.id().equals(selected)).findFirst().orElseThrow();if(contract.state()==CompanyBook.ContractState.OFFERED&&contract.counterparty().canSpend(actor.getServer(),me))form(forms,"COMPANY_CONTRACT_ACCEPT");if(contract.state()==CompanyBook.ContractState.OFFERED&&b.permits(c.id(),me,CompanyBook.Permission.TRADE))form(forms,"COMPANY_CONTRACT_CANCEL");if(contract.state()==CompanyBook.ContractState.ACCEPTED&&contract.kind()!=CompanyBook.ContractKind.EMPLOYMENT)form(forms,"COMPANY_CONTRACT_COMPLETE");}
            else if(kind.equals("company_share_offer")){if(selectedRow.getUUID("Buyer").equals(me))form(forms,"COMPANY_SHARE_ACCEPT");if(selectedRow.getUUID("Seller").equals(me))form(forms,"COMPANY_SHARE_CANCEL");}
            else if(kind.equals("company_vote")){var v=b.votes().stream().filter(x->x.id().equals(selected)).findFirst().orElseThrow();if(v.state().equals("OPEN")&&v.electorate().containsKey(me)&&!v.ballots().containsKey(me))form(forms,"COMPANY_VOTE","Yes=true|false");if(v.state().equals("OPEN")&&v.yes()>v.total()/2)form(forms,"COMPANY_EXECUTE_VOTE");}
        }
        formLabels(forms);result.put("Forms",forms);String search=q.getString("Search").toLowerCase(Locale.ROOT);all.removeIf(r->!r.getString("Name").toLowerCase(Locale.ROOT).contains(search));all.sort(Comparator.comparing(t->t.getString("Name"),String.CASE_INSENSITIVE_ORDER));int page=Math.max(0,Math.min(q.getInt("Page"),Math.max(0,(all.size()-1)/32)));var rows=new ListTag();for(var r:all.subList(Math.min(all.size(),page*32),Math.min(all.size(),(page+1)*32)))rows.add(r);result.put("Rows",rows);result.putInt("Page",page);result.putInt("Total",all.size());result.putInt("Pages",Math.max(1,(all.size()+31)/32));return result;
    }
    private static CompanyBook.Company selectedCompany(CompanyBook b,UUID selected){return b.find(selected).orElseGet(()->b.all().stream().filter(c->c.employees().stream().anyMatch(e->CompanyBook.stable(c.id(),"employee/"+e.player()).equals(selected))||c.assets().stream().anyMatch(a->a.id().equals(selected))||b.invites().stream().anyMatch(i->i.company().equals(c.id())&&i.id().equals(selected))||b.contracts().stream().anyMatch(i->i.company().equals(c.id())&&i.id().equals(selected))||b.shareOffers().stream().anyMatch(i->i.company().equals(c.id())&&i.id().equals(selected))||b.votes().stream().anyMatch(i->i.company().equals(c.id())&&i.id().equals(selected))).findFirst().orElseThrow(()->new IllegalArgumentException("company_unavailable")));}
    public static void execute(ServerPlayer actor,CompoundTag q){
        if(!q.hasUUID("Request")||!q.getBoolean("Confirmed"))throw new IllegalArgumentException("company_confirmation");var e=EconomyManager.get(actor.serverLevel());var b=e.companies();UUID me=actor.getUUID(),request=CompanyBook.stable(me,q.getUUID("Request").toString());String action=q.getString("Action"),fingerprint=action+"/"+(q.hasUUID("Selected")?q.getUUID("Selected"):"")+"/"+q.getCompound("Values");if(b.commandDone(request,fingerprint))return;var v=q.getCompound("Values");long now=System.currentTimeMillis();
        if(action.equals("COMPANY_CREATE")){UUID city=id(v,"City");if(CityManager.get(actor.serverLevel()).getCity(city)==null)throw new IllegalArgumentException("company_city");b.create(request,me,v.getString("Name"),city,now);b.commandCompleted(request,fingerprint);return;}
        if(action.equals("COMPANY_TAX")){UUID cityId=id(v,"City");var city=CityManager.get(actor.serverLevel()).getCity(cityId);if(city==null||!city.isAdmin(me))throw new IllegalArgumentException("company_permission");b.tax(cityId,Math.toIntExact(number(v,"TaxBps")));b.commandCompleted(request,fingerprint);return;}
        if(!q.hasUUID("Selected"))throw new IllegalArgumentException("company_unavailable");UUID selected=q.getUUID("Selected");var c=selectedCompany(b,selected);switch(action){
            case "COMPANY_DEPOSIT"->b.deposit(c.id(),me,number(v,"Amount"));
            case "COMPANY_WITHDRAW"->b.withdraw(c.id(),me,number(v,"Amount"),now);
            case "COMPANY_INVITE"->b.invite(c.id(),me,id(v,"Player"),CompanyBook.Role.valueOf(v.getString("Role")),number(v,"Salary"),now);
            case "COMPANY_ACCEPT_JOB"->b.acceptJob(selected,me,now);
            case "COMPANY_DECLINE_JOB"->b.declineJob(selected,me);
            case "COMPANY_CANCEL_INVITE"->b.cancelInvitation(selected,me);
            case "COMPANY_EMPLOYEE_ROLE"->b.employeeRole(c.id(),me,employee(c,selected).player(),CompanyBook.Role.valueOf(v.getString("Role")));
            case "COMPANY_SALARY_OFFER"->b.amendSalary(c.id(),me,employee(c,selected).player(),number(v,"Salary"),now);
            case "COMPANY_EMPLOYEE_END"->b.endEmployment(c.id(),me,employee(c,selected).player(),now);
            case "COMPANY_ASSET_REGISTER"->registerAsset(actor,c,v);
            case "COMPANY_ASSET_REMOVE"->b.removeAsset(c.id(),me,selected);
            case "COMPANY_CONTRACT_CREATE"->createContract(actor,c,v,now);
            case "COMPANY_INFRA_CONTRACT"->infrastructureContract(actor,c,v,now);
            case "COMPANY_CONTRACT_ACCEPT"->{var contract=contract(b,selected);if(!contract.counterparty().canSpend(actor.getServer(),me))throw new IllegalArgumentException("company_permission");b.acceptContract(selected,now);}
            case "COMPANY_CONTRACT_COMPLETE"->{var contract=contract(b,selected);if(!b.permits(c.id(),me,CompanyBook.Permission.TRADE)&&!contract.counterparty().operates(actor.getServer(),me))throw new IllegalArgumentException("company_permission");if(!proved(actor,contract))throw new IllegalArgumentException("company_contract_unproved");b.completeContract(selected);}
            case "COMPANY_CONTRACT_CANCEL"->b.cancelContract(selected,me);
            case "COMPANY_SHARE_OFFER"->b.offerShares(c.id(),me,id(v,"Player"),Math.toIntExact(number(v,"Shares")),number(v,"Price"),now,expires(v,now));
            case "COMPANY_SHARE_ACCEPT"->b.acceptShares(selected,me,now);
            case "COMPANY_SHARE_CANCEL"->b.cancelShares(selected,me);
            case "COMPANY_PROPOSE"->{var decision=CompanyBook.Decision.valueOf(v.getString("Decision"));UUID target=decision==CompanyBook.Decision.CITY?id(v,"City"):Set.of(CompanyBook.Decision.DIRECTOR,CompanyBook.Decision.ISSUE_SHARES).contains(decision)?id(v,"Player"):null;if(decision==CompanyBook.Decision.CITY&&CityManager.get(actor.serverLevel()).getCity(target)==null)throw new IllegalArgumentException("company_city");b.propose(c.id(),me,decision,target,number(v,"Amount"),v.getString("Terms"),now);}
            case "COMPANY_VOTE"->{var vote=b.votes().stream().filter(x->x.id().equals(selected)).findFirst().orElseThrow();validateDecision(actor,vote);b.vote(selected,me,Boolean.parseBoolean(v.getString("Yes")),now);}
            case "COMPANY_EXECUTE_VOTE"->{if(!b.shareholder(c.id(),me))throw new IllegalArgumentException("company_shareholder");var vote=b.votes().stream().filter(x->x.id().equals(selected)).findFirst().orElseThrow();validateDecision(actor,vote);b.executeApproved(selected,now);}
            default->throw new IllegalArgumentException("company_action");
        }b.commandCompleted(request,fingerprint);
    }
    private static String percent(int basisPoints){return java.math.BigDecimal.valueOf(basisPoints).movePointLeft(2).stripTrailingZeros().toPlainString()+"%";}
    private static long number(CompoundTag v,String key){return Long.parseLong(v.getString(key));}
    private static UUID id(CompoundTag v,String key){return UUID.fromString(v.getString(key));}
    private static long expires(CompoundTag v,long now){long hours=number(v,"Hours");if(hours<1||hours>720)throw new IllegalArgumentException("company_expiry");return Math.addExact(now,Math.multiplyExact(hours,3_600_000L));}
    private static CompanyBook.Employee employee(CompanyBook.Company c,UUID selected){return c.employees().stream().filter(x->CompanyBook.stable(c.id(),"employee/"+x.player()).equals(selected)).findFirst().orElseThrow();}
    private static CompanyBook.Contract contract(CompanyBook b,UUID id){return b.contracts().stream().filter(x->x.id().equals(id)).findFirst().orElseThrow();}
    private static void registerAsset(ServerPlayer actor,CompanyBook.Company c,CompoundTag values){String[] source=values.getString("Asset").split("/",-1);if(source.length!=2)throw new IllegalArgumentException("company_asset");UUID reference=UUID.fromString(source[1]);var kind=CompanyBook.AssetKind.valueOf(values.getString("AssetKind"));String expected=Set.of(CompanyBook.AssetKind.PRODUCTION,CompanyBook.AssetKind.STORE,CompanyBook.AssetKind.WAREHOUSE).contains(kind)?"WAREHOUSE":kind.name();if(!source[0].equals(expected))throw new IllegalArgumentException("company_asset");OwnerRef owner=CompanyBook.owner(c.id());String name;
        switch(kind){case WAREHOUSE,PRODUCTION,STORE->{var w=CargoWarehouseRegistry.get(actor.getServer()).find(reference).orElseThrow();if(!CargoWarehouseRegistry.access(actor.getServer(),w).owner().equals(owner))throw new IllegalArgumentException("company_asset_owner");name=w.name();}
            case TRAIN->{var t=CargoTrainRegistry.find(actor.getServer(),reference).orElseThrow();if(!CargoOwners.get(actor.getServer()).owner("train/"+reference,t.ownerId()).equals(owner))throw new IllegalArgumentException("company_asset_owner");name=t.displayName();}
            case POINT->{var p=CargoPointRegistry.find(actor.getServer(),reference).orElseThrow();if(!CargoOwners.point(actor.getServer(),p).equals(owner))throw new IllegalArgumentException("company_asset_owner");name=p.name();}
            case ROAD->{var road=EconomyManager.get(actor.serverLevel()).roadTolls().road(reference).orElseThrow();if(!road.owner().equals(owner))throw new IllegalArgumentException("company_asset_owner");name=road.name();}
            default->throw new IllegalArgumentException("company_asset");}book(actor).asset(c.id(),actor.getUUID(),kind,reference,name);
    }
    private static void createContract(ServerPlayer actor,CompanyBook.Company c,CompoundTag v,long now){var order=EconomyManager.get(actor.serverLevel()).cargo().order(id(v,"Order")).orElseThrow();var kind=CompanyBook.ContractKind.valueOf(v.getString("ContractKind"));var own=CompanyBook.owner(c.id());OwnerRef counterparty;long amount;
        if(kind==CompanyBook.ContractKind.SUPPLY){if(!order.payer().equals(own)&&!order.seller().equals(own))throw new IllegalArgumentException("company_contract_order");counterparty=order.payer().equals(own)?order.seller():order.payer();amount=order.goods();}
        else if(kind==CompanyBook.ContractKind.TRANSPORT){if(order.payer().equals(own)){var recipients=order.fees().stream().filter(f->f.amount()>0).map(CargoCommerceBook.Fee::recipient).distinct().toList();if(recipients.size()!=1)throw new IllegalArgumentException("company_contract_multiple_carriers");counterparty=recipients.getFirst();amount=order.fees().stream().mapToLong(CargoCommerceBook.Fee::amount).reduce(0,Math::addExact);}else{amount=order.fees().stream().filter(f->f.recipient().equals(own)).mapToLong(CargoCommerceBook.Fee::amount).reduce(0,Math::addExact);if(amount==0)throw new IllegalArgumentException("company_contract_order");counterparty=order.payer();}}
        else throw new IllegalArgumentException("company_contract_kind");if(counterparty.equals(own))throw new IllegalArgumentException("company_contract_self");book(actor).contract(c.id(),actor.getUUID(),kind,counterparty,order.id(),amount,order.quantity(),v.getString("Terms"),expires(v,now),now);
    }
    private static void infrastructureContract(ServerPlayer actor,CompanyBook.Company c,CompoundTag v,long now){var debt=EconomyManager.get(actor.serverLevel()).roadTolls().debts().stream().filter(d->d.id().equals(id(v,"RoadReceipt"))).findFirst().orElseThrow();var own=CompanyBook.owner(c.id());if(!debt.debtor().equals(own)&&!debt.creditor().equals(own))throw new IllegalArgumentException("company_contract_order");book(actor).contract(c.id(),actor.getUUID(),CompanyBook.ContractKind.INFRASTRUCTURE,debt.debtor().equals(own)?debt.creditor():debt.debtor(),debt.id(),debt.assessed(),0,v.getString("Terms"),expires(v,now),now);}
    private static boolean proved(ServerPlayer actor,CompanyBook.Contract contract){var econ=EconomyManager.get(actor.serverLevel());if(contract.kind()==CompanyBook.ContractKind.INFRASTRUCTURE)return econ.roadTolls().debts().stream().anyMatch(d->d.id().equals(contract.reference())&&d.remaining()==0&&d.assessed()==contract.amount());var order=econ.cargo().order(contract.reference()).orElse(null);if(order==null||order.state()!=CargoCommerceBook.State.SETTLED)return false;var shipment=CargoShipmentRegistry.get(actor.getServer()).find(order.shipment()).orElse(null);return shipment!=null&&shipment.delivered()==shipment.quantity();}
    private static void validateDecision(ServerPlayer actor,CompanyBook.Vote v){if(v.decision()==CompanyBook.Decision.CITY&&CityManager.get(actor.serverLevel()).getCity(v.target())==null)throw new IllegalArgumentException("company_city");if(v.decision()!=CompanyBook.Decision.ARCHIVE)return;var owner=CompanyBook.owner(v.company());var s=actor.getServer();if(CargoWarehouseRegistry.get(s).all().stream().anyMatch(w->CargoWarehouseRegistry.access(s,w).owner().equals(owner))||CargoLineRegistry.get(s).all().stream().anyMatch(l->CargoLineRegistry.access(s,l).owner().equals(owner))||CargoPointRegistry.get(s).points().stream().anyMatch(p->CargoOwners.point(s,p).equals(owner))||CargoTrainRegistry.get(s).registrations().stream().anyMatch(t->CargoOwners.get(s).owner("train/"+t.trainId(),t.ownerId()).equals(owner))||EconomyManager.get(actor.serverLevel()).roadTolls().hasOutstanding(owner)||EconomyManager.get(actor.serverLevel()).cargo().orders().stream().anyMatch(o->!Set.of(CargoCommerceBook.State.SETTLED,CargoCommerceBook.State.CANCELLED,CargoCommerceBook.State.REFUNDED).contains(o.state())&&(o.payer().equals(owner)||o.seller().equals(owner)||o.fees().stream().anyMatch(f->f.recipient().equals(owner)))))throw new IllegalArgumentException("company_obligations");}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(event.getServer().overworld().getGameTime()%200==0)EconomyManager.get(event.getServer().overworld()).companies().payroll(System.currentTimeMillis());}
}
